public IURLProtocolHandler mapIO(String url, IURLProtocolHandler handler,
      boolean unmapUrlOnOpen)
  {
    {
      if (url == null || url.length() <= 0)
        throw new IllegalArgumentException("must pass in non-zero url");
      if (handler == null)
