    if (parts == null) {
      logError("Couldn't read parts");
      return false;
    }

    // Read the file header info (DM_RFIL)
    readFileHeaderInfo();
    if (fileHeaderInfo == null) {
      logError("Couldn't read file header info");
      return false;
