		for(String s : bs){
			if(s.length() != 8) throw new RuntimeException(
					"The length of bit string must be 8  while " + s.length());
			for(char c : s.toCharArray()){
				if(c == '0') bv.append0();
				else if(c == '1') bv.append1();
				else throw new RuntimeException("invalid char '" + c + "' for bit string.");
			}
		}
	}

