public String encodeURL(String strURL)
	{
		String furl = JBackupConstants.BLANK;
		try {
			int iStart = 0;
			for (int i = iStart; i <= strURL.length(); i++)
			{
				if ((i == strURL.length())
					|| (strURL.charAt(i) == '/'))
				{
					if (iStart != i)
						furl += URLEncoder.encode(strURL.substring(iStart, i), ENCODING);
					if (i != strURL.length())
						furl += '/';
					iStart = i + 1;
				}
			}
		} catch (UnsupportedEncodingException ex) {
			ex.printStackTrace();
		}
		return furl;
	}

