        keyToIndex.remove(key);
        keySet.remove(key);


        V removedValue = data.remove(index.intValue());


        for (K nextKey : keyToIndex.keySet())
        {
            Integer nextIndex = keyToIndex.get(nextKey);

            if (nextIndex > index)
            {
                keyToIndex.put(nextKey, nextIndex - 1);
            }
        }


        return removedValue;
    }

